	// the galactic core: a direction in the band (low in the southern sky)
	let core = normalize( vec3f( 0.25, 0.35, - 0.92 ) - pole * dot( vec3f( 0.25, 0.35, - 0.92 ), pole ) );
	let toCore = dot( dir, core );
