	let b = skyParams.meteorB;
	if ( b.w <= 0.0 ) { return vec3f( 0.0 ); }
	let head = normalize( mix( a.xyz, b.xyz, a.w ) );
	let tail = normalize( mix( a.xyz, b.xyz, max( a.w - 0.4, 0.0 ) ) );
	let seg = head - tail;
	let t = clamp( dot( dir - tail, seg ) / max( dot( seg, seg ), 1e-9 ), 0.0, 1.0 );
