		let gap = abs( - viewDepth( _waterSceneDepthAt( uv ) ) - hitV.z );
		let touch = smoothstep( max( b * 0.03, 0.4 ), max( b * 0.015, 0.2 ), gap );
		let hitY = ( frame.invView * vec4f( hitV, 1.0 ) ).y;
